import os
import time
import unicodedata
from flask import Flask, request, abort, send_file, jsonify
from werkzeug.utils import secure_filename
import hashlib
import hmac
import re

app = Flask(__name__)

# Configuration
BASE_DIR = os.path.abspath(os.environ.get('STORAGE_DIR', '/var/app/storage'))
API_SECRET = os.environ.get('API_SECRET', '')
if not API_SECRET:
    raise RuntimeError('API_SECRET must be set')

# Maximum allowed age (in seconds) of a signed request to prevent replay attacks
REQUEST_MAX_AGE = int(os.environ.get('REQUEST_MAX_AGE', '300'))

def constant_time_compare(a: str, b: str) -> bool:
    return hmac.compare_digest(a.encode(), b.encode())

def generate_request_signature(path: str, timestamp: str) -> str:
    msg = f"{path}:{timestamp}".encode()
    return hmac.new(API_SECRET.encode(), msg, hashlib.sha256).hexdigest()

def verify_request_auth(path: str, timestamp: str, signature: str) -> bool:
    # Reject requests with a stale or invalid timestamp (replay protection)
    try:
        ts = int(timestamp)
    except (TypeError, ValueError):
        return False
    now = int(time.time())
    if abs(now - ts) > REQUEST_MAX_AGE:
        return False
    expected = generate_request_signature(path, timestamp)
    return constant_time_compare(expected, signature)

def sanitize_path_component(component: str) -> str:
    """Remove obviously dangerous characters from a path component."""
    # Strip null bytes
    component = component.replace('\x00', '')
    # Remove backslashes (Windows path sep)
    component = component.replace('\\', '')
    # Collapse multiple dots
    component = re.sub(r'\.{2,}', '.', component)
    return component

def validate_path_traversal(requested_path: str) -> bool:
    """Check that the path doesn't contain traversal sequences."""
    # Check for common traversal patterns
    dangerous_patterns = [
        '..', './', '/.', '%2e', '%2f', '%5c',
        '\\', '..\\', '\\..'
    ]
    path_lower = requested_path.lower()
    for pattern in dangerous_patterns:
        if pattern in path_lower:
            return False
    return True

def resolve_file_path(user_path: str) -> str:
    """Resolve the user-requested path to an absolute filesystem path.

    Security: normalizes Unicode FIRST, then validates path traversal.
    This ensures the validation sees the final form of the path.
    """
    # Step 1: Unicode NFC normalization FIRST for consistent validation
    # Must normalize before security checks to prevent bypass via
    # equivalent Unicode representations
    normalized_path = unicodedata.normalize('NFC', user_path)

    # Step 2: Sanitize individual components
    components = normalized_path.split('/')
    sanitized_components = [sanitize_path_component(c) for c in components]
    sanitized_path = '/'.join(sanitized_components)

    # Step 3: Validate no traversal in sanitized+normalized path
    if not validate_path_traversal(sanitized_path):
        return None

    # Step 4: Construct full path
    full_path = os.path.join(BASE_DIR, sanitized_path)

    # Step 5: Resolve to absolute and verify containment
    real_path = os.path.realpath(full_path)
    if not real_path.startswith(BASE_DIR + os.sep) and real_path != BASE_DIR:
        return None

    return real_path

@app.route('/api/v1/files/<path:filepath>')
def serve_file(filepath):
    # Verify authentication
    timestamp = request.headers.get('X-Timestamp', '')
    signature = request.headers.get('X-Signature', '')

    if not timestamp or not signature:
        abort(401)

    if not verify_request_auth(filepath, timestamp, signature):
        abort(403)

    # Resolve and validate path
    resolved = resolve_file_path(filepath)
    if resolved is None:
        abort(400)

    if not os.path.isfile(resolved):
        abort(404)

    return send_file(resolved)

@app.route('/api/v1/list/<path:dirpath>')
def list_directory(dirpath):
    timestamp = request.headers.get('X-Timestamp', '')
    signature = request.headers.get('X-Signature', '')

    if not timestamp or not signature:
        abort(401)

    if not verify_request_auth(dirpath, timestamp, signature):
        abort(403)

    resolved = resolve_file_path(dirpath)
    if resolved is None:
        abort(400)

    if not os.path.isdir(resolved):
        abort(404)

    files = []
    for entry in os.scandir(resolved):
        files.append({
            'name': entry.name,
            'is_dir': entry.is_dir(),
            'size': entry.stat().st_size if entry.is_file() else 0
        })

    return jsonify({'files': files})

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080)
